import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"Цели проектирования","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/intro/design.md","filePath":"ru/development/intro/design.md","lastUpdated":1744252752000}`),a={name:`ru/development/intro/design.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="цели-проектирования" tabindex="-1">Цели проектирования <a class="header-anchor" href="#цели-проектирования" aria-label="Permalink to “Цели проектирования”">​</a></h1><ul><li>Ядро Xray предоставляет платформу, которая поддерживает необходимые функции сетевого прокси, и на ее основе можно выполнять дальнейшую разработку для улучшения пользовательского опыта.</li><li>Кроссплатформенность является основным принципом, чтобы снизить затраты на вторичную разработку.</li></ul><h2 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to “Архитектура”">​</a></h2><p><img src="/assets/framework.Bf6xCZ4u.png" alt="Architecture" width="1206" height="922"></p><p>Ядро состоит из трех уровней: уровня приложений, уровня прокси и транспортного уровня.</p><p>Каждый уровень содержит несколько модулей, которые независимы друг от друга, и модули одного типа могут быть легко заменены.</p><h3 id="уровень-приложении" tabindex="-1">Уровень приложений <a class="header-anchor" href="#уровень-приложении" aria-label="Permalink to “Уровень приложений”">​</a></h3><p>Уровень приложений содержит некоторые функции, которые часто используются на уровне прокси. Эти функции абстрагированы, чтобы их можно было повторно использовать в разных модулях прокси.</p><p>Модули уровня приложений должны быть реализованы чисто программным способом, без привязки к аппаратному обеспечению или платформе.</p><p>Список важных модулей:</p><ul><li>Dispatcher: используется для передачи данных, полученных входящим прокси, исходящему прокси;</li><li>Router: модуль маршрутизации, см. <a href="./../../config/routing.html">настройки маршрутизации</a>;</li><li>DNS: встроенный модуль DNS-сервера;</li><li>Proxy Manager: менеджер прокси;</li></ul><h3 id="уровень-прокси" tabindex="-1">Уровень прокси <a class="header-anchor" href="#уровень-прокси" aria-label="Permalink to “Уровень прокси”">​</a></h3><p>Уровень прокси делится на две части: входящий прокси (Inbound Proxy) и исходящий прокси (Outbound Proxy).</p><p>Эти две части независимы друг от друга, входящий прокси не зависит от какого-либо конкретного исходящего прокси, и наоборот.</p><h4 id="входящии-прокси" tabindex="-1">Входящий прокси <a class="header-anchor" href="#входящии-прокси" aria-label="Permalink to “Входящий прокси”">​</a></h4><ul><li>Реализует интерфейс <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Inbound</a>;</li></ul><h4 id="исходящии-прокси" tabindex="-1">Исходящий прокси <a class="header-anchor" href="#исходящии-прокси" aria-label="Permalink to “Исходящий прокси”">​</a></h4><ul><li>Реализует интерфейс <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Outbound</a>;</li></ul><h3 id="транспортныи-уровень" tabindex="-1">Транспортный уровень <a class="header-anchor" href="#транспортныи-уровень" aria-label="Permalink to “Транспортный уровень”">​</a></h3><p>Транспортный уровень предоставляет модули инструментов, связанных с передачей сетевых данных.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};